/**
 * Render a component instance to HTML.
 *
 * @param  \Illuminate\View\Component  $component
 * @return string
 */
public static function renderComponent(Component $component)
{
    $data = $component->data();

    $view = value($component->resolveView(), $data);

    if ($view instanceof View) {
        return $view->with($data)->render();
    } elseif ($view instanceof Htmlable) {
        return $view->toHtml();
    } else {
        return Container::getInstance()
            ->make(ViewFactory::class)
            ->make($view, $data)
            ->render();
    }
}

/**
 * Store the blocks that do not receive compilation.
 *
 * @param  string  $value
 * @return string
 */
protected function storeUncompiledBlocks($value)
{
    if (str_contains($value, '@verbatim')) {
        $value = (new ComponentTagCompiler(
            $this->classComponentAliases, $this->classComponentNamespaces, $this
        ))->storeVerbatimBlocks($value);
    }

    if (str_contains($value, '@php')) {
        $value = $this->storePhpBlocks($value);
    }

    return $value;
}

/**
 * Store the PHP blocks and replace them with a temporary placeholder.
 *
 * @param  string  $value
 * @return string
 */
protected function storePhpBlocks($value)
{
    return preg_replace_callback('/(?<!@)@php(.*?)@endphp/s', function ($matches) {
        return $this->storeRawBlock("<?php{$matches[1]}?>");
    }, $value);
}

/**
 * Store a raw block and return a unique raw placeholder.
 *
 * @param  string  $value
 * @return string
 */
public function storeRawBlock($value)
{
    return $this->getRawPlaceholder(
        array_push($this->rawBlocks, $value) - 1
    );
}

/**
 * Compile the component tags.
 *
 * @param  string  $value
 * @return string
 */
protected function compileComponentTags($value)
{
    if (! $this->compilesComponentTags) {
        return $value;
    }

    return (new ComponentTagCompiler(
        $this->classComponentAliases, $this->classComponentNamespaces, $this
    ))->compile($value);
}

/**
 * Replace the raw placeholders with the original code stored in the raw blocks.
 *
 * @param  string  $result
 * @return string
 */
protected function restoreRawContent($result)
{
    $result = preg_replace_callback('/'.$this->getRawPlaceholder('(\d+)').'/', function ($matches) {
        return $this->rawBlocks[$matches[1]];
    }, $result);

    $this->rawBlocks = [];

    return $result;
}

/**
 * Get a placeholder to temporarily mark the position of raw blocks.
 *
 * @param  int|string  $replace
 * @return string
 */
protected function getRawPlaceholder($replace)
{
    return str_replace('#', $replace, '@__raw_block_#__@');
}

/**
 * Add the stored footers onto the given content.
 *
 * @param  string  $result
 * @return string
 */
protected function addFooters($result)
{
    return ltrim($result, "\n")
            ."\n".implode("\n", array_reverse($this->footer));
}

/**
 * Parse the tokens from the template.
 *
 * @param  array  $token
 * @return string
 */
protected function parseToken($token)
{
    [$id, $content] = $token;

    if ($id == T_INLINE_HTML) {
        foreach ($this->compilers as $type) {
            $content = $this->{"compile{$type}"}($content);
        }
    }

    return $content;
}

/**
 * Execute the user defined extensions.
 *
 * @param  string  $value
 * @return string
 */
protected function compileExtensions($value)
{
    foreach ($this->extensions as $compiler) {
        $value = $compiler($value, $this);
    }

    return $value;
}

/**
 * Compile Blade statements that start with "@".
 *
 * @param  string  $template
 * @return string
 */
protected function compileStatements($template)
{
    preg_match_all('/\B@(@?\w+(?:::\w+)?)([ \t]*)(\( ( [\S\s]*? ) \))?/x', $template, $matches);

    $offset = 0;

    for ($i = 0; isset($matches[0][$i]); $i++) {
        $match = [
            $matches[0][$i],
            $matches[1][$i],
            $matches[2][$i],
            $matches[3][$i] ?: null,
            $matches[4][$i] ?: null,
        ];

        // Here we check to see if we have properly found the closing parenthesis by
        // regex pattern or not, and will recursively continue on to the next ")"
        // then check again until the tokenizer confirms we find the right one.
        while (isset($match[4]) &&
               Str::endsWith($match[0], ')') &&
               ! $this->hasEvenNumberOfParentheses($match[0])) {
            if (($after = Str::after($template, $match[0])) === $template) {
                break;
            }

            $rest = Str::before($after, ')');

            if (isset($matches[0][$i + 1]) && Str::contains($rest.')', $matches[0][$i + 1])) {
                unset($matches[0][$i + 1]);
                $i++;
            }

            $match[0] = $match[0].$rest.')';
            $match[3] = $match[3].$rest.')';
            $match[4] = $match[4].$rest;
        }

        [$template, $offset] = $this->replaceFirstStatement(
            $match[0],
            $this->compileStatement($match),
            $template,
            $offset
        );
    }

    return $template;
}

/**
 * Replace the first match for a statement compilation operation.
 *
 * @param  string  $search
 * @param  string  $replace
 * @param  string  $subject
 * @param  int  $offset
 * @return array
 */
protected function replaceFirstStatement($search, $replace, $subject, $offset)
{
    $search = (string) $search;

    if ($search === '') {
        return $subject;
    }

    $position = strpos($subject, $search, $offset);

    if ($position !== false) {
        return [
            substr_replace($subject, $replace, $position, strlen($search)),
            $position + strlen($replace),
        ];
    }

    return [$subject, 0];
}

/**
 * Determine if the given expression has the same number of opening and closing parentheses.
 *
 * @param  string  $expression
 * @return bool
 */
protected function hasEvenNumberOfParentheses(string $expression)
{
    $tokens = token_get_all('<?php '.$expression);

    if (Arr::last($tokens) !== ')') {
        return false;
    }

    $opening = 0;
    $closing = 0;

    foreach ($tokens as $token) {
        if ($token == ')') {
            $closing++;
        } elseif ($token == '(') {
            $opening++;
        }
    }

    return $opening === $closing;
}

/**
 * Compile a single Blade @ statement.
 *
 * @param  array  $match
 * @return string
 */
protected function compileStatement($match)
{
    if (str_contains($match[1], '@')) {
        $match[0] = isset($match[3]) ? $match[1].$match[3] : $match[1];
    } elseif (isset($this->customDirectives[$match[1]])) {
        $match[0] = $this->callCustomDirective($match[1], Arr::get($match, 3));
    } elseif (method_exists($this, $method = 'compile'.ucfirst($match[1]))) {
        $match[0] = $this->$method(Arr::get($match, 3));
    } else {
        return $match[0];
    }

    return isset($match[3]) ? $match[0] : $match[0].$match[2];
}

/**
 * Call the given directive with the given value.
 *
 * @param  string  $name
 * @param  string|null  $value
 * @return string
 */
protected function callCustomDirective($name, $value)
{
    $value ??= '';

    if (str_starts_with($value, '(') && str_ends_with($value, ')')) {
        $value = Str::substr($value, 1, -1);
    }

    return call_user_func($this->customDirectives[$name], trim($value));
}

/**
 * Strip the parentheses from the given expression.
 *
 * @param  string  $expression
 * @return string
 */
public function stripParentheses($expression)
{
    if (Str::startsWith($expression, '(')) {
        $expression = substr($expression, 1, -1);
    }

    return $expression;
}

/**
 * Register a custom Blade compiler.
